// ── Scroll reveal ──────────────────────────────────────────────────────────────
function Reveal({ children, delay = 0 }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setVisible(true); obs.disconnect(); } }, { threshold: 0.1 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return (
    <div ref={ref} style={{ opacity: visible ? 1 : 0, transform: visible ? "translateY(0)" : "translateY(28px)", transition: `opacity 0.65s ease ${delay}ms, transform 0.65s ease ${delay}ms` }}>
      {children}
    </div>
  );
}

// ── Standard card (solid, no glass/blur) ────────────────────────────────────
function Glass({ children, style = {}, hover = false, cyan = false, violet = false, projectTheme }) {
  const [hov, setHov] = useState(false);
  const accent = violet ? "#0F766E" : "#2563EB";
        const projectStyles = projectTheme === "signal"
          ? { background: "#E6FFFA", border: "1px solid #5EEAD4", borderTop: "4px solid #0F766E", borderRadius: 18, boxShadow: hov ? "0 18px 36px rgba(15,118,110,0.2)" : "0 10px 24px rgba(15,118,110,0.1)" }
    : projectTheme === "editorial"
      ? { background: "#F1F5F9", border: "1px solid #94A3B8", borderTop: "4px solid #334155", borderRadius: 18, boxShadow: hov ? "0 18px 36px rgba(15,23,42,0.2)" : "0 10px 24px rgba(15,23,42,0.1)" }
      : {};
  return (
    <div onMouseEnter={() => setHov(true)} onMouseLeave={() => setHov(false)} style={{
      background: "#FFFFFF",
      border: `1px solid ${(cyan || violet) && hov ? accent + "80" : "#E2E8F0"}`,
      borderRadius: 12,
      transform: hover && hov ? "translateY(-4px)" : "translateY(0)",
      boxShadow: hover && hov ? "0 10px 28px rgba(15,23,42,0.18)" : "0 1px 2px rgba(15,23,42,0.06)",
      transition: "transform 0.2s ease, box-shadow 0.2s ease, border 0.2s ease",
      ...projectStyles,
      ...style,
    }}>{children}</div>
  );
}

// ── Tag ────────────────────────────────────────────────────────────────────────
function Tag({ label, color = "#2563EB" }) {
  return <span style={{ background: `${color}18`, color, border: `1px solid ${color}30`, borderRadius: 6, padding: "3px 10px", fontSize: 12, fontWeight: 600 }}>{label}</span>;
}

